INSERT INTO `ExampleSentence` VALUES (6939,3213,'明日の試験はとても難しいですから、頑張ってください。','Ashita no shiken wa totemo muzukashii desu kara, ganbatte kudasai.','Karena ujian besok sangat sulit, berjuanglah.',1),(6940,3213,'来月、日本語能力試験(JLPT)を 受検しようと 思っています。','Raigetsu, nihongo nouryoku shiken (JLPT) wo juken shiyou to omotteimasu.','Bulan depan, saya berencana mengikuti Ujian Kemampuan Bahasa Jepang (JLPT).',1),(6941,3213,'毎日 この 薬を 飲めば、すぐに 効験が 現れるでしょう。','Mainichi kono kusuri wo nomeba, suguni kouken ga arawareru deshou.','Jika Anda minum obat ini setiap hari, khasiatnya akan segera terlihat.',1),(6942,3213,'日本へ留学したことは、私にとって良い経験になりました。','Nihon he ryuugaku shita koto wa, watashi ni totte yoi keiken ni narimashita.','Belajar di Jepang telah menjadi pengalaman yang baik bagi saya.',1),(6943,3213,'化学ので, 水の性質を調べる実験を行いました。','Kagaku no jugyou de, mizu no seishitsu wo shiraberu jikken wo okonaimashita.','Dalam kelas kimia, kami melakukan eksperimen untuk memeriksa sifat-sifat air.',1),(6949,3215,'宿題が多すぎて、昨日は寝る時間がありませんでした。','Shukudai ga oosugite, kinou wa neru jikan ga arimasen deshita.','Karena PR terlalu banyak, kemarin saya tidak punya waktu tidur.',1),(6950,3215,'今日のゼミでは、卒業論文の論題について議論します。','Kyou no zemi dewa, sotsugyou ronbun no rondai ni tsuite giron shimasu.','Di seminar hari ini, kami akan mendiskusikan tema tesis kelulusan.',1),(6951,3215,'会議で 面白い 話題が 出ています。','Kaigi de omoshiroi wadai ga deteimasu.','Dalam rapat, muncul topik yang menarik.',1),(6952,3215,'彼女は自分の留学経験を題材にして小説を書きました。','Kanojo wa jibun no ryuugaku keiken wo daizai ni shite shousetsu wo kakimashita.','Dia menulis novel berdasarkan pengalaman belajarnya di luar negeri.',1),(6953,3215,'今週は課題がたくさんありますから、とても忙しいです。','Konshuu wa kadai ga takusan arimasu kara, totemo isogashii desu.','Karena minggu ini ada banyak tugas, saya sangat sibuk.',1),(6984,3228,'受信の意味を調べます。','受信 no imi wo shirabemasu.','Memeriksa arti dari 受信 (Menerima Pesan).',1),(6985,3228,'受験について勉強します。','受験 ni tsuite benkyou shimasu.','Belajar tentang 受験 (Mengikuti Ujian).',1),(6992,3232,'労働の意味を調べます。','労働 no imi wo shirabemasu.','Memeriksa arti dari 労働 (Tenaga Kerja).',1),(6993,3232,'共働きについて勉強します。','共働き ni tsuite benkyou shimasu.','Belajar tentang 共働き (Suami Istri Bekerja).',1),(6996,3234,'技術の意味を調べます。','技術 no imi wo shirabemasu.','Memeriksa arti dari 技術 (Teknologi).',1),(6997,3234,'特技について勉強します。','特技 ni tsuite benkyou shimasu.','Belajar tentang 特技 (Keahlian Khusus).',1),(7008,3240,'意見の意味を調べます。','意見 no imi wo shirabemasu.','Memeriksa arti dari 意見 (Pendapat).',1),(7009,3240,'見学について勉強します。','見学 ni tsuite benkyou shimasu.','Belajar tentang 見学 (Studi Banding).',1),(7014,3243,'昔話の意味を調べます。','昔話 no imi wo shirabemasu.','Memeriksa arti dari 昔話 (Dongeng Kuno).',1),(7015,3243,'大昔について勉強します。','大昔 ni tsuite benkyou shimasu.','Belajar tentang 大昔 (Zaman Purbakala).',1),(7022,3247,'時間の意味を調べます。','時間 no imi wo shirabemasu.','Memeriksa arti dari 時間 (Waktu / Jam).',1),(7023,3247,'人間について勉強します。','人間 ni tsuite benkyou shimasu.','Belajar tentang 人間 (Manusia).',1),(7024,3248,'変化の意味を調べます。','変化 no imi wo shirabemasu.','Memeriksa arti dari 変化 (Perubahan).',1),(7025,3248,'大変について勉強します。','大変 ni tsuite benkyou shimasu.','Belajar tentang 大変 (Sangat / Berat).',1),(7026,3249,'変化の意味を調べます。','変化 no imi wo shirabemasu.','Memeriksa arti dari 変化 (Perubahan).',1),(7027,3249,'文化について勉強します。','文化 ni tsuite benkyou shimasu.','Belajar tentang 文化 (Kebudayaan).',1),(7028,3250,'発見の意味を調べます。','発見 no imi wo shirabemasu.','Memeriksa arti dari 発見 (Penemuan).',1),(7029,3250,'発表について勉強します。','発表 ni tsuite benkyou shimasu.','Belajar tentang 発表 (Pengumuman).',1),(7030,3251,'展開の意味を調べます。','展開 no imi wo shirabemasu.','Memeriksa arti dari 展開 (Perkembangan).',1),(7031,3251,'展示について勉強します。','展示 ni tsuite benkyou shimasu.','Belajar tentang 展示 (Pameran).',1),(7032,3252,'進歩の意味を調べます。','進歩 no imi wo shirabemasu.','Memeriksa arti dari 進歩 (Kemajuan).',1),(7033,3252,'進化について勉強します。','進化 ni tsuite benkyou shimasu.','Belajar tentang 進化 (Evolusi).',1),(7034,3253,'成功の意味を調べます。','成功 no imi wo shirabemasu.','Memerik