INSERT INTO `SemanticRelation` VALUES (12872,3221,'体 ：tubuh\n調 ：kondisi, penyesuaian\nHubungan makna antar kanji 体 dan 調 menjadi 体調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"keadaan atau kondisi kesehatan tubuh seseorang.\"',14973),(12873,3221,'好 ：baik\n調 ：keadaan\nHubungan makna antar kanji 好 dan 調 menjadi 好調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"keadaan yang baik atau performa yang sedang meningkat.\"',14974),(12874,3221,'不 ：tidak\n調 ：keadaan\nHubungan makna antar kanji 不 dan 調 menjadi 不調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"kondisi yang tidak baik atau mengalami gangguan.\"',14975),(12875,3221,'快 ：nyaman, menyenangkan\n調 ：keadaan\nHubungan makna antar kanji 快 dan 調 menjadi 快調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"keadaan yang sangat baik, sehat, atau suatu aktivitas yang berjalan dengan lancar.\"',14976),(12876,3221,'順 ：sesuai urutan\n調 ：keadaan\nHubungan makna antar kanji 順 dan 調 menjadi 順調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"suatu kegiatan atau proses yang berlangsung sesuai rencana tanpa mengalami hambatan.\"',14977),(12877,3221,'高 ：tinggi\n調 ：keadaan\nHubungan makna antar kanji 高 dan 調 menjadi 高調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"keadaan yang meningkat atau berada pada tingkat yang tinggi.\"',14978),(12878,3221,'低 ：rendah\n調 ：keadaan\nHubungan makna antar kanji 低 dan 調 menjadi 低調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"keadaan yang menurun, kurang aktif, atau tidak berkembang.\"',14979),(12879,3221,'口 ：mulut\n調 ：nada, cara\nHubungan makna antar kanji 口 dan 調 menjadi 口調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"cara seseorang berbicara atau menyampaikan sesuatu melalui nada dan gaya berbicara.\"',14980),(12880,3221,'語 ：bahasa\n調 ：nada\nHubungan makna antar kanji 語 dan 調 menjadi 語調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"gaya bahasa atau nada yang digunakan seseorang dalam berkomunikasi.\"',14981),(12881,3221,'声 ：suara\n調 ：nada\nHubungan makna antar kanji 声 dan 調 menjadi 声調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"tinggi rendah atau irama suara ketika mengucapkan suatu kata atau kalimat.\"',14982),(12882,3221,'音 ：bunyi\n調 ：irama\nHubungan makna antar kanji 音 dan 調 menjadi 音調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"keselarasan tinggi rendah nada dalam bunyi atau musik.\"',14983),(12883,3221,'調 ：menyelidiki\n査 ：memeriksa\nHubungan makna antar kanji 調 dan 査 menjadi 調査, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"kegiatan memeriksa atau menyelidiki suatu objek secara sistematis untuk memperoleh data atau informasi.\"',14984),(12884,3221,'調 ：menyelidiki\n書 ：dokumen\nHubungan makna antar kanji 調 dan 書 menjadi 調書, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"dokumen yang berisi hasil pemeriksaan, penyelidikan, atau pencatatan suatu peristiwa.\"',14985),(12885,3221,'調 ：menyepakati\n印 ：tanda tangan / cap\nHubungan makna antar kanji 調 dan 印 menjadi 調印, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"kegiatan menandatangani suatu dokumen setelah isi perjanjian disepakati oleh para pihak.\"',14986),(12886,3221,'調 ：mengatur\n達 ：memperoleh\nHubungan makna antar kanji 調 dan 達 menjadi 調達, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"kegiatan mengatur dan memperoleh barang atau perlengkapan yang diperlukan.\"',14987),(12887,3221,'調 ：mengolah\n理 ：mengatur\nHubungan makna antar kanji 調 dan 理 menjadi 調理, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"mengolah dan mengatur bahan makanan hingga siap dikonsumsi.\"',14988),(12888,3221,'調 ：menyesuaikan\n合 ：menggabungkan\nHubungan makna antar kanji 調 dan 合 menjadi 調合, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"mencampurkan beberapa bahan dengan komposisi yang sesuai sehingga menghasilkan campuran yang diinginkan.\"',14989),(12889,3221,'調 ：menyiapkan\n製 ：membuat\nHubungan makna antar kanji 調 dan 製 menjadi 調製, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"menyiapkan atau membuat sesuatu sesuai kebutuhan atau tujuan tertentu.\"',14990),(12890,3221,'調 ：menyiapkan\n薬 ：obat\nHubungan makna antar kanji 調 dan 薬 menjadi 調薬, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"menyiapkan atau meracik obat sesuai dengan resep atau kebutuhan pasien.\"',14991),(12891,3221,'調味 ：memberi rasa\n料 ：bahan\nHubungan makna antara 調味 dan 料 menjadi 調味料, menunjukkan bahwa gabungan kedua unsur tersebut membentuk sebuah makna \"bahan yang digunakan untuk menyesuaikan atau memperkaya cita rasa makanan.\"',14993),(12892,3221,'強 ：kuat\n調 ：menonjolkan\nHubungan makna antar kanji 強 dan 調 menjadi 強調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"memberikan penekanan yang kuat pada bagian yang dianggap penting.\"',14994),(12893,3221,'歩 ：berjalan\n調 ：irama\nHubungan makna antar kanji 歩 dan 調 menjadi 歩調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"menyelaraskan langkah atau gerakan agar berjalan bersama secara teratur.\"',14995),(12894,3221,'変 ：berubah\n調 ：keadaan\nHubungan makna antar kanji 変 dan 調 menjadi 変調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"perubahan kondisi dari keadaan yang normal menjadi keadaan yang berbeda.\"',14996),(12895,3221,'移 ：memindahkan\n調 ：nada\nHubungan makna antar kanji 移 dan 調 menjadi 移調, menunjukkan bahwa gabungan kedua kanji tersebut membentuk sebuah makna \"memindahkan tinggi rendah nada suatu lagu tanpa mengubah susunan melodinya.\"',14997),(12960,3212,'Hubungan makna antara kanji 試 dan 験 menjadi 試験, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna “ujian yang dilakukan un